contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount));
        require(amount > 0);
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        uint before = address(this).balance;
        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint afterBal = address(this).balance;
        assert(!reverted && afterBal <= before);
    }
    receive() external payable {}
}

